
<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Plus, Search, EditPen, Delete, Box } from '@element-plus/icons-vue'
import { adminCategoryApi, adminMedicineApi } from '@/api'
import type { Category, Medicine, PageData } from '@/types'
import { dateTime, money } from '@/utils'
const router=useRouter();const data=ref<PageData<Medicine>>({records:[],current:1,size:10,total:0,pages:0});const categories=ref<Category[]>([]);const query=reactive({page:1,size:10,keyword:'',categoryId:undefined as number|undefined,status:undefined as number|undefined,stockStatus:'ALL'});const dialog=ref(false);const saving=ref(false);const editId=ref<number>();
const blank=()=>({categoryId:undefined as number|undefined,medicineName:'',imageUrl:'/images/medicine/cold.svg',description:'',usageInstruction:'请按商品说明使用。',precautions:'请阅读包装注意事项。',price:0.01,stock:0,warningStock:5,prescriptionRequired:0,status:1});const form=reactive(blank())
const load=async(page=query.page)=>{query.page=page;data.value=await adminMedicineApi.page({...query,stockStatus:query.stockStatus==='ALL'?undefined:query.stockStatus})};onMounted(async()=>{categories.value=await adminCategoryApi.page({page:1,size:100}).then(v=>v.records);await load()})
const open=(item?:Medicine)=>{editId.value=item?.id;Object.assign(form,item?{categoryId:item.categoryId,medicineName:item.medicineName,imageUrl:item.imageUrl||'',description:item.description||'',usageInstruction:item.usageInstruction||'',precautions:item.precautions||'',price:item.price,stock:item.stock,warningStock:item.warningStock,prescriptionRequired:item.prescriptionRequired??0,status:item.status}:blank());dialog.value=true}
const save=async()=>{if(!form.categoryId||!form.medicineName)return ElMessage.warning('请填写分类和药品名称');saving.value=true;try{if(editId.value)await adminMedicineApi.update(editId.value,form);else await adminMedicineApi.add(form);ElMessage.success('保存成功');dialog.value=false;await load()}finally{saving.value=false}}
const remove=async(item:Medicine)=>{await ElMessageBox.confirm(`确认逻辑删除“${item.medicineName}”吗？建议历史订单商品优先下架而不是删除。`,'删除药品',{type:'warning'});await adminMedicineApi.remove(item.id);ElMessage.success('已删除');await load()}
const toggle=async(item:Medicine)=>{await adminMedicineApi.status(item.id,item.status?0:1);ElMessage.success('状态已更新');await load(data.value.current)}
const adjust=()=>router.push('/warehouse')
</script>
<template><div><div class="admin-page-head"><div><span class="eyebrow">MEDICINE MANAGEMENT</span><h1>药品管理</h1><p>维护药品资料、价格、预警阈值与上下架状态；实际库存只能由批次业务改变。</p></div><el-button type="primary" :icon="Plus" @click="open()">新增药品</el-button></div><section class="control-card table-card"><div class="filter-row medicine-filter"><el-input v-model="query.keyword" :prefix-icon="Search" placeholder="搜索药品名称" clearable @keyup.enter="load(1)" @clear="load(1)"/><el-select v-model="query.categoryId" clearable placeholder="全部分类" @change="load(1)"><el-option v-for="c in categories" :key="c.id" :label="c.categoryName" :value="c.id"/></el-select><el-select v-model="query.status" clearable placeholder="全部状态" @change="load(1)"><el-option label="上架" :value="1"/><el-option label="下架" :value="0"/></el-select><el-select v-model="query.stockStatus" @change="load(1)"><el-option label="全部库存" value="ALL"/><el-option label="库存正常" value="NORMAL"/><el-option label="库存预警" value="LOW"/><el-option label="已缺货" value="OUT"/></el-select><el-button type="primary" @click="load(1)">查询</el-button></div><el-table :data="data.records" stripe><el-table-column label="药品" min-width="250"><template #default="{row}"><div class="medicine-cell"><img v-if="row.imageUrl" :src="row.imageUrl"/><span v-else>药</span><div><b>{{row.medicineName}}</b><small>{{row.categoryName}} · {{row.description||'暂无简介'}}</small></div></div></template></el-table-column><el-table-column label="价格" width="110"><template #default="{row}"><b class="price">{{money(row.price)}}</b></template></el-table-column><el-table-column label="库存" width="130"><template #default="{row}"><span :class="['stock',{'low':row.isLowStock,'out':row.stock<=0}]">{{row.stock}} 件</span><small class="warning-text">预警 {{row.warningStock}}</small></template></el-table-column><el-table-column label="上架" width="95"><template #default="{row}"><el-switch :model-value="row.status===1" @change="toggle(row)"/></template></el-table-column><el-table-column label="更新时间" width="165"><template #default="{row}">{{dateTime(row.updateTime)}}</template></el-table-column><el-table-column label="操作" width="225" fixed="right"><template #default="{row}"><el-button text type="primary" :icon="EditPen" @click="open(row)">编辑</el-button><el-button text type="warning" :icon="Box" @click="adjust">批次库存</el-button><el-button text type="danger" :icon="Delete" @click="remove(row)">删除</el-button></template></el-table-column></el-table></section><div class="pagination"><el-pagination background layout="total, prev, pager, next" :current-page="data.current" :page-size="data.size" :total="data.total" @current-change="load"/></div><el-dialog v-model="dialog" :title="editId?'编辑药品':'新增药品'" width="min(720px,94%)"><el-form label-position="top"><div class="form-two"><el-form-item label="所属分类" required><el-select v-model="form.categoryId" placeholder="请选择分类"><el-option v-for="c in categories" :key="c.id" :label="c.categoryName" :value="c.id"/></el-select></el-form-item><el-form-item label="药品名称" required><el-input v-model="form.medicineName" maxlength="100"/></el-form-item></div><el-form-item label="图片地址"><el-input v-model="form.imageUrl" placeholder="例如：/images/medicine/cold.svg"/></el-form-item><el-form-item label="药品简介"><el-input v-model="form.description" type="textarea" :rows="2" maxlength="500"/></el-form-item><div class="form-two"><el-form-item label="销售价格" required><el-input-number v-model="form.price" :min="0.01" :precision="2" :step="1"/></el-form-item><el-form-item label="当前库存（由批次汇总）"><el-input-number v-model="form.stock" :min="0" disabled/></el-form-item></div><div class="form-two"><el-form-item label="库存预警值" required><el-input-number v-model="form.warningStock" :min="0"/></el-form-item><el-form-item label="药品类型"><el-switch v-model="form.prescriptionRequired" :active-value="1" :inactive-value="0" active-text="处方药" inactive-text="非处方药"/></el-form-item></div><div class="form-two"><el-form-item label="上架状态"><el-switch v-model="form.status" :active-value="1" :inactive-value="0" active-text="上架" inactive-text="下架"/></el-form-item></div><el-form-item label="使用说明"><el-input v-model="form.usageInstruction" type="textarea" :rows="2" maxlength="1000"/></el-form-item><el-form-item label="注意事项"><el-input v-model="form.precautions" type="textarea" :rows="2" maxlength="1000"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog></div></template>
<style scoped>.eyebrow{font-size:11px;color:#1677ff;letter-spacing:2px;font-weight:700}.admin-page-head h1{font-size:27px;margin:6px 0}.admin-page-head p{margin:0;color:#8491a4;font-size:13px}.medicine-filter .el-input{width:245px}.medicine-filter .el-select{width:140px}.medicine-cell{display:flex;align-items:center;gap:10px}.medicine-cell img,.medicine-cell>span{width:42px;height:42px;border-radius:11px;background:#eaf5ff;object-fit:cover;display:grid;place-items:center;color:#1677ff}.medicine-cell>div{min-width:0}.medicine-cell b,.medicine-cell small{display:block}.medicine-cell b{font-size:13px}.medicine-cell small{font-size:11px;color:#8a98aa;margin-top:4px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:185px}.price{color:#ff6d2c}.stock{font-size:13px;color:#19b98a}.stock.low{color:#ff8a34}.stock.out{color:#f04438}.warning-text{display:block;font-size:10px;color:#9aa6b7;margin-top:3px}.form-two{display:grid;grid-template-columns:1fr 1fr;gap:14px}.form-two .el-select,.form-two .el-input-number{width:100%}@media(max-width:700px){.medicine-filter .el-input{width:100%;flex-basis:100%}.form-two{grid-template-columns:1fr}}</style>
